import {querySounds,soundCatalogFilters,catalogSummary} from './sound-catalog.js';
import {INSTRUMENTS,makeTrack} from './music.js';
import {samplePreset,normalizeSampler} from './sampler-core.js';
import {sampleLibrary} from './sample-library.js';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createInstrumentBrowserUI({getProject,getRevision,modal,toast,protectedChange,onAdd,onAdded=()=>{},showSamplePalette,library=sampleLibrary,doc=globalThis.document}){
 const $=s=>doc.querySelector(s);let serial=0;
 return function showInstrumentBrowser(){
 const at=getRevision(),ticket=++serial,total=catalogSummary().total;let loading=false,limit=24;
 modal('Add an instrument',`<div class="instrument-browser"><p>${total} playable sampled sounds. Acoustic recordings, SoundFont patches and original EDM synthesis are labeled separately. Adding a sound creates an empty track; it never composes or plays automatically.</p><button id="sample-palette-open" class="quiet">Use recordings on synth tracks · review first</button><div class="clip-fields sound-browser-filters"><label for="instrument-search">Find a sound<input id="instrument-search" type="search" maxlength="120" placeholder="Guitar, choir, brass, Reese…" autocomplete="off"></label><label for="instrument-category">Collection or family<select id="instrument-category">${soundCatalogFilters().map(c=>`<option value="${escape(c.id)}">${escape(c.name)}</option>`).join('')}</select></label></div><p id="instrument-count" role="status" aria-live="polite"></p><div id="instrument-results" class="instrument-list"></div><button id="instrument-more" class="quiet" hidden>Show 24 more</button><details><summary>Original built-in synths</summary><div class="instrument-list">${Object.entries(INSTRUMENTS).map(([id,i])=>`<button class="instrument-choice" data-instrument="${id}">${escape(i.name)}</button>`).join('')}</div></details><div id="add-instrument-error" role="status"></div></div>`);
 const root=$('.instrument-browser'),panel=$('#add-instrument-error'),current=()=>ticket===serial&&$('#modal').open&&$('.instrument-browser')===root;
 const renderSounds=()=>{if(!current()||loading)return;const result=querySounds({query:$('#instrument-search').value,category:$('#instrument-category').value,limit});$('#instrument-results').innerHTML=result.entries.map(e=>`<button class="instrument-choice sound-browser-choice" data-instrument="${e.instrument}" data-sample-preset="${e.id}"><strong>${escape(e.name)}</strong><small>${escape(e.category)} · ${escape(e.sourceLabel)}</small></button>`).join('')||'<p>No matching sound. Try another name or family.</p>';$('#instrument-count').textContent=`${result.total} matching sounds · ${result.entries.length} shown · ${total} in library`;$('#instrument-more').hidden=!result.hasMore;};
 $('#instrument-category').value='featured';$('#instrument-search').oninput=()=>{limit=24;renderSounds()};$('#instrument-category').onchange=()=>{limit=24;renderSounds()};$('#instrument-more').onclick=()=>{limit=Math.min(256,limit+24);renderSounds()};$('#sample-palette-open').onclick=showSamplePalette;
 root.onclick=async e=>{const b=e.target.closest('[data-instrument]');if(!b||!root.contains(b)||loading)return;try{if(at!==getRevision()||!current())throw Error('The project changed. Reopen the instrument browser.');if(getProject().tracks.length>=16)throw Error('A project supports up to 16 tracks.');const t=makeTrack(b.dataset.instrument);
  if(b.dataset.samplePreset){loading=true;for(const el of root.querySelectorAll('input,select,button'))el.disabled=true;panel.textContent='Loading and verifying bundled samples…';t.sampler=normalizeSampler(t.instrument,{preset:b.dataset.samplePreset});t.name=samplePreset(t.sampler.preset).name;await library.loadPreset(t.sampler.preset);if(at!==getRevision()||!current())throw Error('The project or window changed; no track was added.');}
  const apply=({fallback=false}={})=>{if((!fallback&&!current())||ticket!==serial||at!==getRevision())return;if(onAdd(t)){$('#modal').close();onAdded(t);toast('Added '+t.name+'. Draw a few notes to begin.');}};
  if(t.sampler)await protectedChange(apply,'Before adding a sampled instrument · '+getProject().name);else apply();
 }catch(error){if(current())panel.textContent=error.message;}finally{loading=false;if(current())for(const el of root.querySelectorAll('input,select,button'))el.disabled=false;}};
 renderSounds();

 };
}
